# ---------------------------------------------------------------- endpoint


def test_http_checkpoint_returns_200_compact_json():
    body = {"report": _evolution(), "start": ET2, "end": ET3}
    response = client.post(GEN_PATH, json=body)
    assert response.status_code == 200
    expected_proof = _proof(ET2, ET3)
