        (OTHER, ET3),
        (ET2, OTHER),
        (OTHER, OTHER),
    ],
)
def test_invalid_times_or_missing_boundaries_raise(start, end):
    with pytest.raises(ValueError):
        bundle_evolution_checkpoint_bundle_evolution_checkpoint(
